import psycopg2

try:
    # Conexão com o banco Entregas usando o usuário produtos
    conn = psycopg2.connect(
        dbname="Entregas",
        user="produtos",
        password="Ajuda123!",
        host="localhost",
        port="5432",
    )
    print("Conexão OK!")

    cur = conn.cursor()

    # Teste rápido: criar uma linha de exemplo
    cur.execute(
        "INSERT INTO dim_cliente (nome_cliente, segmento, cidade) VALUES (%s, %s, %s)",
        ("Cliente Teste", "Varejo", "São Paulo"),
    )

    conn.commit()

    # Verificar se inseriu
    cur.execute("SELECT * FROM dim_cliente;")
    print("Linhas na tabela:", cur.fetchall())

    cur.close()
    conn.close()
    print("Teste concluído com sucesso!")

except Exception as e:
    print("Erro:", e)
